// ===== Code in JavaScript2 : validate input + build Gemini request =====
// แอป (inspectors/ocr_n8n.py) ส่ง POST form-urlencoded ฟิลด์ 'image_b64'
// → n8n แปลงให้อยู่ใน $json.body.image_b64
// โหนดนี้: ตรวจ base64 / ชนิดภาพ / ขนาด แล้วประกอบ request body ของ
// Gemini ไว้ให้โหนด HTTP Request ใช้ตรงๆ (อย่าลืม: temperature ต้อง = 0)

const item = $input.first().json;
const body = item.body ?? item;            // รองรับทั้ง form และ JSON body

let b64 = String(body.image_b64 ?? body.image ?? '').trim();

// เผื่อบางตัวส่งมาเป็น data URI ("data:image/jpeg;base64,....")
const dataUri = b64.match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/is);
if (dataUri) b64 = dataUri[1];
b64 = b64.replace(/\s+/g, '');
// form-urlencoded อาจแปลง '+' เป็นช่องว่างมาแล้ว — ใส่กลับ
// (requests ฝั่ง Python encode ถูกต้องอยู่แล้ว บรรทัดนี้กันเครื่องมือทดสอบอื่น)
b64 = b64.replace(/ /g, '+');

let valid = true;
let error = '';

if (!b64) {
  valid = false;
  error = "missing form field 'image_b64'";
} else if (b64.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(b64)) {
  valid = false;
  error = "'image_b64' is not valid base64";
}

// อ่าน magic bytes เพื่อบอก mimeType ที่ถูกต้องให้ Gemini
let mimeType = 'image/jpeg';
if (valid) {
  const head = Buffer.from(b64.slice(0, 32), 'base64');
  if (head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4e) {
    mimeType = 'image/png';
  } else if (head[0] === 0xff && head[1] === 0xd8) {
    mimeType = 'image/jpeg';
  } else if (head[0] === 0x52 && head[1] === 0x49 && head[2] === 0x46 &&
             head[8] === 0x57 && head[9] === 0x45) {
    mimeType = 'image/webp';
  } else {
    valid = false;
    error = 'unsupported image format (expected JPEG / PNG / WebP)';
  }
}

const sizeBytes = Math.floor(b64.length * 3 / 4);
if (valid && sizeBytes > 19 * 1024 * 1024) {
  // เพดาน inline image ของ Gemini ~20MB — กันไว้ก่อนยิงจริง
  valid = false;
  error = `image too large: ${(sizeBytes / 1048576).toFixed(1)} MB (limit ~19 MB)`;
}

const PROMPT = "You are a verbatim transcription engine for printed packaging artwork.\nTranscribe ALL text visible in the image EXACTLY as printed,\ncharacter-by-character, in every language present (English, Spanish,\nArabic, Thai, ...).\n\nSTRICT RULES:\n- DO NOT correct spelling, grammar, or punctuation. If a word looks\n  misspelled, transcribe the misspelling exactly as printed.\n- DO NOT add, omit, translate, or normalize any character.\n- Preserve digits, units, and punctuation exactly (e.g. \"16.12 LBS.\",\n  \"(7.31 kg)\", \"\u00a1...!\").\n- Keep reading order top-to-bottom, left-to-right; right-to-left for\n  Arabic. One text element per line.\n- If a region is too small/blurry to read with confidence, transcribe\n  what you can and lower the confidence for that block. Never guess.\n\nReturn ONLY JSON:\n{\n  \"text\": \"<all text, one element per line>\",\n  \"blocks\": [\n    {\"text\": \"<element>\", \"bbox\": [x, y, w, h], \"conf\": 0.0-1.0}\n  ],\n  \"engine\": \"gemini-2.5-flash\"\n}";

// Structured Output: บังคับ Gemini ตอบ JSON ตาม schema เสมอ
const responseSchema = {
  type: 'OBJECT',
  properties: {
    text: { type: 'STRING' },
    blocks: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          text: { type: 'STRING' },
          bbox: { type: 'ARRAY', items: { type: 'NUMBER' } },
          conf: { type: 'NUMBER' },
        },
        required: ['text', 'conf'],
      },
    },
    engine: { type: 'STRING' },
  },
  required: ['text'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT },
      { inlineData: { mimeType, data: b64 } },
    ],
  }],
  generationConfig: {
    temperature: 0,          // ห้ามแก้ — งานถอดความต้อง deterministic
    topP: 1,
    maxOutputTokens: 16384,
    responseMimeType: 'application/json',
    responseSchema,
    // gemini-2.5-flash เปิด thinking เป็นค่า default — งาน transcription
    // ไม่ต้องคิด ปิดเพื่อให้เร็ว/ถูกลง (ลบ 2 บรรทัดนี้ถ้าใช้รุ่นที่ไม่รองรับ)
    thinkingConfig: { thinkingBudget: 0 },
  },
};

return [{
  json: {
    valid,
    error,
    mime_type: mimeType,
    size_kb: Math.round(sizeBytes / 102.4) / 10,
    gemini_request: geminiRequest,
  },
}];

// ===== Code in JavaScript : parse Gemini response → app contract =====
// แอปคาดหวัง JSON: {"text": "...", "blocks": [...], "engine": "..."}
// (ดู inspectors/ocr_n8n.py — parser ฝั่งนั้น permissive แต่ส่งให้ตรง
//  contract ไว้ก่อนดีที่สุด)

const r = $input.first().json;

if (r.error) {
  // Vertex/Gemini ตอบ error object (quota, permission, model not found ฯลฯ)
  // โยนทิ้งให้ n8n คืน HTTP 500 → ฝั่งแอปจะรายงาน "webhook request failed"
  throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);
}

const cand = (r.candidates ?? [])[0] ?? {};
const finishReason = cand.finishReason ?? '';
const raw = ((cand.content ?? {}).parts ?? [])
  .map((p) => p.text ?? '')
  .join('\n')
  .trim();

// ปกติ responseMimeType=application/json ทำให้ raw เป็น JSON ตรงๆ อยู่แล้ว
// แต่กันเหนียว: ตัด code fence / ดึงก้อน {...} แรกออกมา
let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try {
  parsed = JSON.parse(s);
} catch (e) {
  const i = s.indexOf('{');
  const j = s.lastIndexOf('}');
  if (i >= 0 && j > i) {
    try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) { /* noop */ }
  }
}

let text = '';
let blocks = [];
let warning;

if (parsed && typeof parsed === 'object') {
  text = typeof parsed.text === 'string' ? parsed.text : '';
  if (Array.isArray(parsed.blocks)) {
    blocks = parsed.blocks
      .filter((b) => b && typeof b === 'object' && String(b.text ?? '').trim())
      .map((b) => ({
        text: String(b.text).trim(),
        bbox: (Array.isArray(b.bbox) && b.bbox.length === 4)
          ? b.bbox.map(Number)
          : null,
        conf: Number(b.conf ?? 0) || 0,
      }));
  }
  if (!text && blocks.length) text = blocks.map((b) => b.text).join('\n');
} else {
  // model ไม่คืน JSON — ส่ง raw text กลับดีกว่าล้มทั้ง request
  text = raw;
  warning = 'model did not return valid JSON; raw text passed through';
}

if (!text && finishReason && finishReason !== 'STOP') {
  warning = `empty transcription, finishReason=${finishReason}`;
}

return [{
  json: {
    text,
    blocks,
    engine: (parsed && typeof parsed.engine === 'string' && parsed.engine)
      ? parsed.engine
      : 'gemini-2.5-flash',
    ...(warning ? { warning } : {}),
    usage: r.usageMetadata ?? null,
  },
}];
